import { registerWebComponents } from '@domg-wc/common';
import { VlFormLabelComponent, VlInputFieldMaskedComponent } from '@domg-wc/components/form';

// Registreer eigen masks bij het entry point, vóór er een vl-input-field-masked met dat mask op de pagina komt: de
// component leest zijn mask in connectedCallback en maakt de opmaak één keer, in firstUpdated. Een onbekend mask geeft
// geen fout; het veld krijgt dan geen opmaak. De import hierboven registreert vl-input-field-masked al, dus een
// element dat dan al in de HTML van de pagina staat, leest zijn mask vóór setMasks loopt. Voeg de HTML hierboven pas
// na setMasks toe, bv. vanuit je app. setMasks vervangt eerder geregistreerde eigen masks (de vaste masks blijven),
// dus geef ze allemaal in één keer mee.
const CUSTOM_MASK = {
    blocks: [8, 4],
    delimiters: ['-'],
    numericOnly: true,
    numeralPositiveOnly: true,
    regex: /^[0-9]{12}$/,
};

VlInputFieldMaskedComponent.setMasks({ 'custom-mask': CUSTOM_MASK });

registerWebComponents([VlInputFieldMaskedComponent, VlFormLabelComponent]);
